    h, w = len(grid), len(grid[0])
    bg = Counter(x for row in grid for x in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for r, row in enumerate(grid):
        # Extend a horizontal colored run that begins at the left edge,
        # filling the remaining background cells with color 1.
        if row[0] != bg:
            color = row[0]
            k = 0
            while k < w and row[k] == color:
                k += 1
            if k < w and all(x == bg for x in row[k:]):
                for c in range(k, w):
                    out[r][c] = 1
    return out
